using BmsDesktop.Domain;
using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Security;
public sealed class BootstrapAdminService { private readonly Database _db; public BootstrapAdminService(Database db)=>_db=db; public async Task<bool> NeedsBootstrapAsync(){await using var cn=await _db.OpenAsync();await using var c=new NpgsqlCommand("select not exists(select 1 from app_users where role='ADMIN' and is_active=true)",cn);return Convert.ToBoolean(await c.ExecuteScalarAsync());} public async Task<Guid> CreateFirstAdminAsync(string username,string displayName,string password){if(string.IsNullOrWhiteSpace(username)||password.Length<10)throw new ArgumentException("Username wajib dan password minimal 10 karakter.");return await TransactionGuard.RunAsync(_db,async(cn,tx)=>{await using(var x=new NpgsqlCommand("select exists(select 1 from app_users)",cn,tx)){if(Convert.ToBoolean(await x.ExecuteScalarAsync()))throw new InvalidOperationException("Bootstrap hanya untuk database baru tanpa akun.");}var id=Guid.NewGuid();var hash=PasswordHasher.Hash(password);await using var c=new NpgsqlCommand("insert into app_users(id,username,display_name,password_hash,role,is_active) values(@id,@u,@d,@p,'ADMIN',true)",cn,tx);c.Parameters.AddWithValue("id",id);c.Parameters.AddWithValue("u",username.Trim());c.Parameters.AddWithValue("d",displayName.Trim());c.Parameters.AddWithValue("p",hash);await c.ExecuteNonQueryAsync();return id;});} }
